from science_v2.k import Unit
U = Unit("s7u01")

U.q("E", "1.1", "O1", "Ali says: 'Science is a list of facts that never change.' Which is the best reply?", ("Science changes when new evidence is found", "Yes – scientific ideas are tested and improved with evidence."), [("He is right: facts never change", "Ideas such as the model of the atom have changed with new evidence."), ("Science is only opinions", "Scientific ideas are backed by evidence, not just opinion.")])
U.asn("1.1", "O1", "Is each statement about science always, sometimes or never true?", [("A scientific idea can be tested", "Always true"), ("One experiment proves an idea for ever", "Never true"), ("New evidence changes a scientific idea", "Sometimes true")], "Scientific ideas must be testable; they are supported (not proved for ever) by evidence and can change when new evidence appears.")
U.q("F", "1.2", "O3", "Mia tests whether the size of a ball changes how high it bounces. Which must she keep the same?", ("The height she drops each ball from", "Yes – only the size should change, so the test is fair."), [("The size of the ball", "That is the variable she is changing."), ("The height of the bounce", "That is what she measures."), ("Nothing – keeping things the same does not matter", "If other things change too, she cannot tell what caused the difference.")])
U.q("E", "1.2", "O4", "Tom repeats an experiment 3 times and gets 12 s, 13 s and 31 s. What should he do with 31 s?", ("Treat it as an anomaly: check it and repeat that reading", "An anomalous result does not fit the pattern; check it before using it."), [("Use it in the mean as it is", "It is far from the others and would make the mean misleading."), ("Delete all three results", "12 s and 13 s agree well and are useful.")])
U.q("E", "1.3", "O5", "Leo smells a chemical by putting his nose right over the test tube. What should he do instead?", ("Waft the air towards his nose with his hand", "Wafting brings only a little of the gas to the nose."), [("Breathe in deeply to be sure", "That could harm him."), ("Taste it instead", "Never taste chemicals in a laboratory.")])
U.q("R", "1.4", "O6", "A new medicine works well in tests on 20 people. What should scientists do next before everyone uses it?", ("Test it on many more people and check for side effects", "Larger trials show whether it is safe and works for most people."), [("Sell it straight away", "20 people is a small sample."), ("Stop testing because it worked", "Side effects may only show up in larger groups.")])
V2 = U.V2
